import pytest

from pylint.config._pylint_config.generate_command import handle_generate_command
import pylint.config._pylint_config.generate_command as gc


class DummyConfig:
    def __init__(self, interactive: bool):
        self.interactive = interactive


class DummyLinter:
    def __init__(self, interactive: bool):
        self.config = DummyConfig(interactive)


class TestHandleGenerateCommand:
    def test_handle_generate_command_interactive_true(self, monkeypatch):
        called = {"linter": None}

        def fake_generate_interactive_config(linter):
            called["linter"] = linter

        monkeypatch.setattr(gc, "generate_interactive_config", fake_generate_interactive_config)

        linter = DummyLinter(True)

        result = handle_generate_command(linter)

        assert result == 0
        assert called["linter"] is linter

    def test_handle_generate_command_interactive_false_prints_help(self, monkeypatch, capsys):
        def fake_get_subparser_help(linter, subparser_name):
            assert subparser_name == "generate"
            return "GENERATE HELP"

        def fake_generate_interactive_config(linter):
            raise AssertionError("generate_interactive_config should not be called when interactive is False")

        monkeypatch.setattr(gc, "get_subparser_help", fake_get_subparser_help)
        monkeypatch.setattr(gc, "generate_interactive_config", fake_generate_interactive_config)

        linter = DummyLinter(False)

        result = handle_generate_command(linter)
        captured = capsys.readouterr()

        assert result == 32
        assert "GENERATE HELP" in captured.out

