    def _check_property_with_parameters(self, node):
        self.calls.append("_check_property_with_parameters")

    def _check_first_arg_for_type(self, node, is_metaclass):
        self.calls.append("_check_first_arg_for_type")

    def _check_init(self, node, klass):
        self.calls.append("_check_init")

    def _check_signature(self, node, parent_function, klass):
        self.calls.append("_check_signature")

    def _check_invalid_overridden_method(self, node, parent_function):
        self.calls.append("_check_invalid_overridden_method")

    def add_message(self, *args, **kwargs):
        self.calls.append(("add_message", args, kwargs))


def get_function_node(code: str, class_name: str, func_name: str):
    module = parse(code)
    klass = None
    for n in module.body:
        if isinstance(n, nodes.ClassDef) and n.name == class_name:
            klass = n
            break
    if klass is None:
        return None
    for n in klass.body:
        if isinstance(n, nodes.FunctionDef) and n.name == func_name:
            return n
    return None


def get_top_level_function(code: str, func_name: str):
    module = parse(code)
    for n in module.body:
        if isinstance(n, nodes.FunctionDef) and n.name == func_name:
            return n
    return None


def test_visit_functiondef_ignores_non_method():
    code = """
def foo():
    pass
"""
    fn = get_top_level_function(code, "foo")
    assert isinstance(fn, nodes.FunctionDef)

    checker = TestableClassChecker(linter=DummyLinter())
    checker.visit_functiondef(fn)

    assert checker.calls == []


def test_visit_functiondef_init_calls_check_init():
    code = """
class A:
    def __init__(self):
        pass
"""
    init_fn = get_function_node(code, "A", "__init__")
    assert isinstance(init_fn, nodes.FunctionDef)

    checker = TestableClassChecker(linter=DummyLinter())
    checker.visit_functiondef(init_fn)

    # Expect the sequence: useless_super_delegation, property_with_parameters, first_arg_for_type, init
    assert checker.calls[:4] == [
        "_check_useless_super_delegation",
        "_check_property_with_parameters",
        "_check_first_arg_for_type",
        "_check_init",
    ]
    # Ensure that override checks were not invoked for __init__
    assert "_check_signature" not in checker.calls
    assert "_check_invalid_overridden_method" not in checker.calls


def test_visit_functiondef_overridden_signature_checked():
    code = """
class Parent:
    def f(self, x):
        return x

class Child(Parent):
    def f(self, x):
        return x
"""
    fn = get_function_node(code, "Child", "f")
    assert isinstance(fn, nodes.FunctionDef)

    checker = TestableClassChecker(linter=DummyLinter())
    checker.visit_functiondef(fn)

    # Should detect an overridden method and call signature/invalid checks
    assert "_check_signature" in checker.calls
    assert "_check_invalid_overridden_method" in checker.calls

