import pytest

from pylint.graph import get_cycles


class TestGetCycles:
    @staticmethod
    def _cycle_set_contains(cycle, vs: set[str]) -> bool:
        s = set(cycle)
        if s == vs:
            return True
        if cycle and len(cycle) >= 2 and cycle[0] == cycle[-1] and set(cycle[:-1]) == vs:
            return True
        return False

    def test_empty_graph_returns_empty_tuple(self):
        assert get_cycles({}) == ()

    def test_no_cycles_returns_empty_list(self):
        graph = {'A': {'B'}, 'B': {'C'}, 'C': set()}
        cycles = get_cycles(graph)
        assert isinstance(cycles, list)
        assert cycles == []

    def test_simple_cycle(self):
        graph = {'A': {'B'}, 'B': {'A'}}
        cycles = get_cycles(graph)
        assert isinstance(cycles, list)
        assert any(self._cycle_set_contains(cycle, {'A', 'B'}) for cycle in cycles)

